"""
    Takes a file name with potentially invalid characters, and substitutes the
    symbol in, in place of those invalid characters.

    Arguments:
    fname:   str (name of file)
    symbol:  str (symbol to substitute invalid characters to)

    Returns:
    str with the new file name containing symbol in place of any illegal
    characters
    """
def fname_remove_invalid_chars(fname: str, symbol: Any = '-') -> str {
    INVALID_CHARS = ["/", ":"];
    for char in INVALID_CHARS {
        if (fname.find(char) != -1) {
            temp = `list(fname);
            temp[fname.find(char)] = symbol;
            fname = "".join(temp);
        }
    }
    return fname;
}

test_blocks:
test "t0" {
    assert (fname_remove_invalid_chars("file.txt", "-") == "file.txt");;
}

test "t1" {
    assert (fname_remove_invalid_chars(r"dir/file.txt") == "dir-file.txt");;
}

test "t2" {
    assert (fname_remove_invalid_chars("file.txt", ":") == "file.txt");;
}

test "t3" {
    assert (fname_remove_invalid_chars(r"dir:file.txt", ":") == "dir:file.txt");;
}

test "t4" {
    assert (fname_remove_invalid_chars(r"dir/file.txt", ":") == "dir:file.txt");;
}

test "t5" {
    assert (fname_remove_invalid_chars(r"dir:file.txt", "-") == "dir-file.txt");;
}

test "t6" {
    assert (
        fname_remove_invalid_chars('A file with spaces.txt') == 'A file with spaces.txt'
    );;
}

test "t7" {
    assert (fname_remove_invalid_chars("file.txt") == "file.txt");;
}

test "t8" {
    assert (fname_remove_invalid_chars(r"dir/file.txt", "-") == "dir-file.txt");;
}

test "t9" {
    assert (fname_remove_invalid_chars("file.txt", r"/") == "file.txt");;
}
